from pathlib import Path
import re
p=Path('js/modules/academic.js'); s=p.read_text(encoding='utf-8')
cssp=Path('css/design-system.css'); css=cssp.read_text(encoding='utf-8')
tp=Path('tests/academic-separate-pages.test.js'); test=tp.read_text(encoding='utf-8')

# Replace only plans() list renderer; weekly detail helpers stay untouched.
m=re.search(r"function plans\(\)\{.*?\}\nfunction openPlanSelection\(\)\{",s,re.S)
if not m: raise SystemExit('plans/openPlanSelection sınırı bulunamadı')
plans_fn=r'''function plans(){const all=arr('yillikPlanTanimlari').filter(p=>match([p.dersAdi,p.seviye,p.egitimOgretimYili])).sort((a,b)=>Number(a.seviye||0)-Number(b.seviye||0)||(a.dersAdi||'').localeCompare(b.dersAdi||'','tr'));if(planView.planId){const p=arr('yillikPlanTanimlari').find(x=>x.id===planView.planId);if(p)return planDetail(p);planView={planId:'',weekIndex:0}}const tid=planTeacherId(),tracked=planTracked(),canEdit=YillikPlanService?._yaziYetkisiVar?.();return{count:all.length,html:`<section class="ka-stack ka-plans-page"><article class="ka-plan-hero"><div><span class="ka-plan-hero__icon">📚</span><div><h2>Yıllık Plan</h2><p>MEB ünitelendirilmiş yıllık ders planları — hafta bazlı takip</p></div></div>${canEdit?`<div class="ka-plan-actions"><button class="ka-btn ka-btn--secondary ka-btn--sm" type="button" data-plan-headings>🏷️ Ana Başlıklar</button><button class="ka-btn ka-btn--sm" type="button" data-plan-new>＋ Yeni Plan Tanımı</button></div>`:''}</article><section class="ka-card"><div class="ka-card__header ka-row ka-row--between"><div><strong>🎯 Takip Ettiğim Planlar</strong><div class="ka-muted">Bugünkü haftanın içeriğine doğrudan ulaşın.</div></div>${tid?'<button class="ka-btn ka-btn--secondary ka-btn--sm" type="button" data-plan-select>＋ Plan Ekle / Değiştir</button>':''}</div><div class="ka-card__body ka-stack">${!tid?'<div class="ka-empty">Profilinize bağlı bir öğretmen kaydı bulunamadı.</div>':tracked.length?tracked.map(p=>{const i=planCurrentWeekIndex(p),theme=planTheme(p,i);return`<button class="ka-plan-row" type="button" data-plan-open="${esc(p.id)}"><span><strong>${esc(p.dersAdi||'Yıllık plan')}</strong><small>${esc(p.seviye?` · ${p.seviye}. Sınıf`:'')}${theme?`<br>Bu hafta: ${esc(theme.slice(0,90))}${theme.length>90?'…':''}`:''}</small></span><span>›</span></button>`}).join(''):'<div class="ka-empty">Henüz bir plan seçmediniz. “Plan Ekle / Değiştir” ile başlayın.</div>'}</div></section>${canEdit?`<section class="ka-card"><div class="ka-card__header"><strong>⚙️ Plan Tanımları (Yönetim)</strong></div><div class="ka-card__body ka-stack">${all.length?all.map(p=>`<div class="ka-plan-admin-row"><button class="ka-plan-admin-main" type="button" data-plan-open="${esc(p.id)}"><span><strong>${esc(p.dersAdi||'Yıllık plan')}</strong><small>${esc([p.seviye?`${p.seviye}. Sınıf`:'',p.egitimOgretimYili,`${(p.satirlar||[]).length} hafta`,`${(p.sutunlar||[]).length} başlık`].filter(Boolean).join(' · '))}</small></span><span>›</span></button><button class="ka-btn ka-btn--secondary ka-btn--sm" type="button" data-plan-edit="${esc(p.id)}">Düzenle</button></div>`).join(''):'<div class="ka-empty">Yıllık plan tanımı bulunamadı.</div>'}</div></section>`:''}</section>`}}
function openPlanSelection(){'''
s=s[:m.start()]+plans_fn+s[m.end():]

# Insert real old admin model before bindPlans.
anchor='function bindPlans(out){'
idx=s.find(anchor)
if idx<0: raise SystemExit('bindPlans anchor bulunamadı')
admin=r'''function openPlanHeadings(){const rows=arr('yillikPlanBasliklari').slice().sort((a,b)=>Number(a.sira||0)-Number(b.sira||0)),ov=modal('🏷️ Ana Başlıklar',`<p class="ka-muted">Bu havuz bütün yıllık plan tanımlarının ortak başlıklarını içerir.</p><div class="ka-plan-admin-list">${rows.length?rows.map(b=>`<div class="ka-plan-admin-line"><span>${esc(b.ad||'Başlık')}</span><button class="ka-btn ka-btn--danger ka-btn--sm" type="button" data-plan-heading-delete="${esc(b.id)}">Sil</button></div>`).join(''):'<div class="ka-empty">Henüz ana başlık yok.</div>'}</div><div class="ka-row"><input data-plan-heading-name placeholder="Yeni başlık adı"><button class="ka-btn ka-btn--secondary" type="button" data-plan-heading-add>Ekle</button></div>`);ov.querySelector('[data-save]').hidden=true;ov.querySelector('[data-plan-heading-add]').onclick=async()=>{const input=ov.querySelector('[data-plan-heading-name]'),ad=input.value.trim();if(!ad)return;try{await YillikPlanService.baslikEkle({ad,sira:rows.length});ov.remove();openPlanHeadings()}catch(e){toast?.(e?.message==='yetkisiz'?'Bu işlem için yetkiniz yok.':'Başlık eklenemedi.')}};ov.querySelectorAll('[data-plan-heading-delete]').forEach(b=>b.onclick=async()=>{const id=b.dataset.planHeadingDelete,used=arr('yillikPlanTanimlari').some(x=>(x.sutunlar||[]).includes(id));if(used&&!confirm('Bu başlık en az bir plan tanımında kullanılıyor. Yine de silinsin mi?'))return;try{await YillikPlanService.baslikSil(id);ov.remove();openPlanHeadings()}catch(e){toast?.('Başlık silinemedi.')}})}
function openPlanDefinition(id=''){const item=id?arr('yillikPlanTanimlari').find(x=>x.id===id):null,headings=arr('yillikPlanBasliklari').slice().sort((a,b)=>Number(a.sira||0)-Number(b.sira||0)),chosen=new Set(item?.sutunlar||[]),year=item?.egitimOgretimYili||`${new Date().getFullYear()}-${new Date().getFullYear()+1}`,ov=modal(item?'Plan Tanımını Düzenle':'Yeni Plan Tanımı',`<div class="ka-grid"><label class="ka-field"><span class="ka-field__label">Ders Adı</span><input data-plan-def-lesson value="${esc(item?.dersAdi||'')}" placeholder="Örn: Fen Bilimleri"></label><label class="ka-field"><span class="ka-field__label">Sınıf Seviyesi</span><select data-plan-def-level>${[1,2,3,4,5,6,7,8].map(x=>`<option value="${x}" ${Number(item?.seviye||1)===x?'selected':''}>${x}. Sınıf</option>`).join('')}</select></label></div><div class="ka-grid"><label class="ka-field"><span class="ka-field__label">Eğitim-Öğretim Yılı</span><input data-plan-def-year value="${esc(year)}" placeholder="2026-2027"></label><label class="ka-field"><span class="ka-field__label">İmza Tarihi</span><input data-plan-def-sign type="date" value="${esc(item?.imzaTarihi||today())}"></label></div><label class="ka-field"><span class="ka-field__label">Okul Adı (isteğe bağlı)</span><input data-plan-def-school value="${esc(item?.okulAdiManuel||'')}"></label><fieldset class="ka-field"><legend class="ka-field__label">Bu Ders Hangi Ana Başlıkları Kullansın?</legend><div class="ka-plan-heading-grid">${headings.length?headings.map(h=>`<label class="ka-check"><input type="checkbox" data-plan-def-heading value="${esc(h.id)}" ${chosen.has(h.id)?'checked':''}> ${esc(h.ad||'Başlık')}</label>`).join(''):'<div class="ka-empty">Önce Ana Başlıklar bölümünden başlık ekleyin.</div>'}</div></fieldset>${item?`<button class="ka-btn ka-btn--secondary" type="button" data-plan-rows>📋 Hafta Satırlarını Düzenle (${(item.satirlar||[]).length})</button>`:''}`,!!item);ov.querySelector('[data-save]').onclick=async()=>{const dersAdi=ov.querySelector('[data-plan-def-lesson]').value.trim();if(!dersAdi)return toast?.('Ders adı zorunludur.');const data={dersAdi,seviye:Number(ov.querySelector('[data-plan-def-level]').value),egitimOgretimYili:ov.querySelector('[data-plan-def-year]').value.trim(),imzaTarihi:ov.querySelector('[data-plan-def-sign]').value||null,okulAdiManuel:ov.querySelector('[data-plan-def-school]').value.trim()||null,sutunlar:[...ov.querySelectorAll('[data-plan-def-heading]:checked')].map(x=>x.value)};if(!item)data.satirlar=[];try{item?await YillikPlanService.tanimGuncelle(item.id,data):await YillikPlanService.tanimEkle(data);ov.remove();toast?.('Plan tanımı kaydedildi.')}catch(e){toast?.(e?.message==='yetkisiz'?'Bu işlem için yetkiniz yok.':'Plan tanımı kaydedilemedi.')}};ov.querySelector('[data-delete]')?.addEventListener('click',async()=>{if(!item||!confirm(`“${item.dersAdi} — ${item.seviye}. Sınıf” plan tanımı silinsin mi?`))return;try{await YillikPlanService.tanimSil(item.id);ov.remove();toast?.('Plan tanımı silindi.')}catch(e){toast?.('Plan tanımı silinemedi.')}});ov.querySelector('[data-plan-rows]')?.addEventListener('click',()=>{ov.remove();openPlanRows(item.id)})}
function openPlanRows(planId){const p=arr('yillikPlanTanimlari').find(x=>x.id===planId);if(!p)return;const rows=p.satirlar||[],ov=modal(`📋 ${esc(p.dersAdi||'Plan')} — Hafta Satırları`,`<div class="ka-plan-admin-list">${rows.length?rows.map((r,i)=>`<div class="ka-plan-admin-line"><span><b>${i+1}. ${esc(r.ay||'')}</b><small>${esc(planDateText(r,p.egitimOgretimYili)||r.hafta||'')}</small></span><div class="ka-row"><button class="ka-btn ka-btn--secondary ka-btn--sm" type="button" data-plan-row-edit="${i}">Düzenle</button><button class="ka-btn ka-btn--danger ka-btn--sm" type="button" data-plan-row-delete="${i}">Sil</button></div></div>`).join(''):'<div class="ka-empty">Henüz hafta satırı yok.</div>'}</div><button class="ka-btn" type="button" data-plan-row-new>＋ Yeni Hafta Ekle</button>`);ov.querySelector('[data-save]').hidden=true;ov.querySelector('[data-plan-row-new]').onclick=()=>{ov.remove();openPlanRowEditor(planId,null)};ov.querySelectorAll('[data-plan-row-edit]').forEach(b=>b.onclick=()=>{ov.remove();openPlanRowEditor(planId,Number(b.dataset.planRowEdit))});ov.querySelectorAll('[data-plan-row-delete]').forEach(b=>b.onclick=async()=>{if(!confirm('Bu hafta satırı silinsin mi?'))return;const next=rows.slice();next.splice(Number(b.dataset.planRowDelete),1);try{await YillikPlanService.tanimGuncelle(planId,{satirlar:next});ov.remove();openPlanRows(planId)}catch(e){toast?.('Hafta silinemedi.')}})}
function openPlanRowEditor(planId,index=null){const p=arr('yillikPlanTanimlari').find(x=>x.id===planId);if(!p)return;const old=index===null?null:(p.satirlar||[])[index],vals=old?.degerler||{},ov=modal(old?'Hafta Satırını Düzenle':'Yeni Hafta Ekle',`<div class="ka-grid"><label class="ka-field"><span class="ka-field__label">Ay</span><input data-plan-row-month value="${esc(old?.ay||'')}" placeholder="EYLÜL"></label><label class="ka-field"><span class="ka-field__label">Hafta (gün aralığı ile)</span><input data-plan-row-week value="${esc(old?.hafta||'')}" placeholder="1.HAFTA(08-14)"></label><label class="ka-field"><span class="ka-field__label">Saat</span><input data-plan-row-hour value="${esc(old?.saat||'')}"></label></div>${(p.sutunlar||[]).map(id=>`<label class="ka-field"><span class="ka-field__label">${esc(planHeadingName(id))}</span><textarea data-plan-row-value="${esc(id)}" rows="4">${esc(vals[id]||'')}</textarea></label>`).join('')||'<div class="ka-empty">Bu plan için ana başlık seçilmemiş.</div>'}`);ov.querySelector('[data-save]').onclick=async()=>{const row={ay:ov.querySelector('[data-plan-row-month]').value.trim(),hafta:ov.querySelector('[data-plan-row-week]').value.trim(),saat:ov.querySelector('[data-plan-row-hour]').value.trim(),degerler:{}};ov.querySelectorAll('[data-plan-row-value]').forEach(x=>{const v=x.value.trim();if(v)row.degerler[x.dataset.planRowValue]=v});const next=(p.satirlar||[]).slice();if(index===null)next.push(row);else next[index]=row;try{await YillikPlanService.tanimGuncelle(planId,{satirlar:next});ov.remove();openPlanRows(planId);toast?.('Hafta kaydedildi.')}catch(e){toast?.(e?.message==='yetkisiz'?'Bu işlem için yetkiniz yok.':'Hafta kaydedilemedi.')}}}
'''
s=s[:idx]+admin+s[idx:]

old="function bindPlans(out){if(!out)return;out.querySelectorAll('[data-plan-open]').forEach"
new="function bindPlans(out){if(!out)return;out.querySelector('[data-plan-headings]')?.addEventListener('click',openPlanHeadings);out.querySelector('[data-plan-new]')?.addEventListener('click',()=>openPlanDefinition(''));out.querySelectorAll('[data-plan-edit]').forEach(b=>b.addEventListener('click',()=>openPlanDefinition(b.dataset.planEdit)));out.querySelectorAll('[data-plan-open]').forEach"
if old not in s: raise SystemExit('bindPlans başlangıcı bulunamadı')
s=s.replace(old,new,1)

if '/* Annual Plan Admin V2 */' in css: raise SystemExit('Annual admin CSS zaten mevcut')
css += r'''

/* Annual Plan Admin V2 */
.ka-plan-actions{display:flex;flex-wrap:wrap;gap:var(--ka-space-2);margin-top:var(--ka-space-4)}.ka-plan-admin-row{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:center;gap:var(--ka-space-2);border-bottom:1px solid var(--ka-border)}.ka-plan-admin-row:last-child{border-bottom:0}.ka-plan-admin-main{min-height:58px;border:0;background:transparent;color:var(--ka-text);display:flex;align-items:center;justify-content:space-between;text-align:left;padding:8px 2px;cursor:pointer}.ka-plan-admin-main strong,.ka-plan-admin-main small{display:block}.ka-plan-admin-main small{margin-top:3px;color:var(--ka-text-muted);font-size:var(--ka-font-size-xs)}.ka-plan-admin-list{display:flex;flex-direction:column;gap:2px;max-height:55dvh;overflow:auto}.ka-plan-admin-line{min-height:52px;display:flex;align-items:center;justify-content:space-between;gap:var(--ka-space-3);padding:8px 2px;border-bottom:1px solid var(--ka-border)}.ka-plan-admin-line>span{display:grid;min-width:0}.ka-plan-admin-line small{color:var(--ka-text-muted);font-size:var(--ka-font-size-xs);margin-top:2px}.ka-plan-heading-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:8px;padding:10px;border:1px solid var(--ka-border);border-radius:var(--ka-radius-md);background:var(--ka-muted-bg)}
@media(max-width:430px){.ka-plan-actions{display:grid;grid-template-columns:1fr 1fr}.ka-plan-actions .ka-btn{width:100%;padding-inline:8px}.ka-plan-admin-row{grid-template-columns:minmax(0,1fr) auto}.ka-plan-admin-line{align-items:flex-start;flex-direction:column}.ka-plan-admin-line>.ka-row{width:100%;justify-content:flex-end}.ka-plan-heading-grid{grid-template-columns:1fr}}
'''

needle="for(const token of ['planCurrentWeekIndex','planTracked','ogretmenYillikPlanSecimleri','yillikPlanNotlari','data-plan-select','data-plan-note','data-plan-prev','data-plan-next']) assert(academic.includes(token),`Yıllık Plan gerçek haftalık takip sözleşmesi eksik: ${token}`);"
if needle not in test: raise SystemExit('Annual plan test anchor bulunamadı')
extra=needle+"\nfor(const token of ['data-plan-headings','data-plan-new','data-plan-edit','openPlanHeadings','openPlanDefinition','openPlanRows','openPlanRowEditor','baslikEkle','baslikSil','tanimEkle','tanimGuncelle','tanimSil']) assert(academic.includes(token),`Yıllık Plan yönetim sözleşmesi eksik: ${token}`);"
test=test.replace(needle,extra,1)

p.write_text(s,encoding='utf-8');cssp.write_text(css,encoding='utf-8');tp.write_text(test,encoding='utf-8')
print('Yıllık Plan yönetim CRUD gerçek eski modele göre taşındı.')
